+                    ok[live[x]] = false;
+                    bad = true;
+                }
+            }
+        }
+        if !bad {
+            for k in live {
+                pieces[k].fine = Some(std::mem::replace(&mut pieces[k].pts, coarse[k].clone()));
+            }
+            return;
+        }
+    }
+}
